arguments.keystrokes:
cat > /app/setup.exp <<'EOF'
#!/usr/bin/expect -f
set timeout 300
spawn qemu-system-x86_64 -m 512 -nographic \
  -cdrom /app/alpine.iso \
  -hda /app/alpine-disk.qcow2 \
  -serial telnet:127.0.0.1:6665,server,nowait
expect { "login: " { } timeout { exit 1 } }
send "root\r"
expect { "# " { } timeout { exit 1 } }
send "apk add telnet inetutils 2>/dev/null; true\r"
expect { "# " { } timeout { exit 1 } }
send "grep -q 6665 /etc/inittab || echo 'tel1::respawn:/usr/sbin/telnetd -l /sbin/getty 115200 tel1' >> /etc/inittab; init q\r"
expect { "# " { } timeout { exit 1 } }
send "sleep 120\r"
expect { "# " { } timeout { exit 1 } }
EOF
chmod +x /app/setup.exp
